rss.channel:
{{ .Title }} - {{ .Site.Title }}
{{ .Permalink }}
{{ .Description | default .Site.Params.description }}
Hugo -- gohugo.io
{{- with .Site.LanguageCode }}{{ . }}{{ end }}
{{- with .Site.Params.Author.email }}
  {{ . }}{{ with $.Site.Params.Author.name }} ({{ . }}){{ end }}
{{- end }}
{{- with .OutputFormats.Get "RSS" }}
  {{ printf "" .Permalink .MediaType | safeHTML }}
{{- end }}
{{- range .RegularPages.ByPublishDate.Reverse | first (.Site.Params.section.rss | default 10) }}
  {{- dict "Page" . "Site" .Site | partial "rss/item.html" }}
{{- end }}
